begin;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
insert into cooksmith.household_pantry_items(id,household_id,name,category,storage_location,quantity,unit,available) values('98000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Synthetic milk','dairy','fridge',0,'L',false);
insert into cooksmith.shopping_list_items(id,household_id,display_name,quantity,unit,category,completed) values
('98000000-0000-4000-8000-000000000010','20000000-0000-4000-8000-000000000001','Synthetic milk',2,'L','dairy_and_eggs',true),
('98000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000001','Synthetic apples',3,null,'produce',true),
('98000000-0000-4000-8000-000000000012','20000000-0000-4000-8000-000000000001','Synthetic paper',1,null,'household',false);
select is((select count(*) from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001')),2::bigint,'Only completed unapplied purchases are offered');
create temporary table reviewed as select jsonb_build_array(jsonb_build_object('name','Synthetic milk','category','dairy','storageLocation','fridge','sources',jsonb_build_array(jsonb_build_object('key',source_key,'token',snapshot_token)))) payload from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001') where shopping_item_id='98000000-0000-4000-8000-000000000010';
select is((select available from cooksmith.household_pantry_items where id='98000000-0000-4000-8000-000000000001'),false,'Review alone does not restore stock');
select lives_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000020',(select payload from reviewed))$$,'Owner applies reviewed purchase atomically');
select is((select available from cooksmith.household_pantry_items where id='98000000-0000-4000-8000-000000000001'),true,'Unavailable Pantry item restored');
select is((select quantity from cooksmith.household_pantry_items where id='98000000-0000-4000-8000-000000000001'),0::numeric,'Legacy quantity was not incremented or invented');
select is((select count(*) from cooksmith.household_pantry_items where name='Synthetic milk'),1::bigint,'Existing match is not duplicated');
select is((select count(*) from cooksmith.shopping_list_items where id='98000000-0000-4000-8000-000000000010' and completed),1::bigint,'Bought Shopping history remains');
select is((select count(*) from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001')),1::bigint,'Excluded purchase remains eligible');
select lives_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000020',(select payload from reviewed))$$,'Exact request retry returns saved result');
update cooksmith.household_pantry_items set available=false where id='98000000-0000-4000-8000-000000000001';
select lives_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001',gen_random_uuid(),(select payload from reviewed))$$,'New operation cannot reapply old purchase');
select is((select available from cooksmith.household_pantry_items where id='98000000-0000-4000-8000-000000000001'),false,'Replay cannot resurrect stock consumed afterwards');
select is((select count(*) from cooksmith.shopping_put_away_receipts),1::bigint,'One durable receipt per source');
select throws_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000020','[{"name":"Other","sources":[]}]')$$,'23514',null,'Operation reuse with changed request is denied');
select throws_ok($$delete from cooksmith.shopping_put_away_receipts$$,'42501',null,'Client cannot delete idempotency evidence');
select throws_ok($$update cooksmith.shopping_put_away_batches set result='{}'$$,'42501',null,'Client cannot rewrite operation evidence');
-- A bad later source rolls back the earlier Pantry insert and all receipts.
create temporary table second_review as select jsonb_build_array(jsonb_build_object('name','Corrected apples','category','produce','storageLocation','produce_storage','sources',jsonb_build_array(jsonb_build_object('key',source_key,'token',snapshot_token)))) payload from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001') where shopping_item_id='98000000-0000-4000-8000-000000000011';
select throws_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001',gen_random_uuid(),(select payload from second_review)||'[{"name":"Invalid","category":"other","storageLocation":"pantry","sources":[{"key":"m:unknown","token":"forged"}]}]'::jsonb)$$,'PT409',null,'One invalid source rejects the complete batch');
select is((select count(*) from cooksmith.household_pantry_items where name='Corrected apples'),0::bigint,'No partial Pantry insert survived');
select is((select count(*) from cooksmith.shopping_put_away_receipts),1::bigint,'No partial receipt survived');
update cooksmith.shopping_list_items set completed=false where id='98000000-0000-4000-8000-000000000011';
select throws_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001',gen_random_uuid(),(select payload from second_review))$$,'PT409',null,'Unbought after review is not applied');
update cooksmith.shopping_list_items set completed=true,quantity=4 where id='98000000-0000-4000-8000-000000000011';
select throws_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001',gen_random_uuid(),(select payload from second_review))$$,'PT409',null,'Changed purchase requires a fresh review');
update second_review set payload=(select jsonb_build_array(jsonb_build_object('name','Corrected apples','category','produce','storageLocation','produce_storage','sources',jsonb_build_array(jsonb_build_object('key',source_key,'token',snapshot_token)))) from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001') where shopping_item_id='98000000-0000-4000-8000-000000000011');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select lives_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001',gen_random_uuid(),(select payload from second_review))$$,'Another active member can apply corrected, selected purchase');
select is((select available from cooksmith.household_pantry_items where name='Corrected apples'),true,'Correction creates available Pantry item');
select is((select quantity from cooksmith.household_pantry_items where name='Corrected apples'),null::numeric,'New Pantry item has no invented quantity');
select is((select storage_location::text from cooksmith.household_pantry_items where name='Corrected apples'),'produce_storage','Current categorisation is retained');
-- Equivalent ingredient rows yield separate receipts and a single Pantry item.
insert into cooksmith.planned_meals(id,household_id,title,meal_date,meal_type) values('98000000-0000-4000-8000-000000000030','20000000-0000-4000-8000-000000000001','Synthetic plan','2026-10-07','dinner');
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000030','[{"name":"synthetic salt","quantity":10,"unit":"g","category":"pantry"},{"name":"synthetic salt","quantity":1,"unit":"tsp","category":"pantry"}]');
select cooksmith.set_shopping_purchase_completed('20000000-0000-4000-8000-000000000001',(select array_agg(id) from cooksmith.shopping_list_items where display_name='synthetic salt'),true);
create temporary table grouped_review as select jsonb_build_array(jsonb_build_object('name','synthetic salt','category','herbs_and_spices','storageLocation','pantry','sources',jsonb_agg(jsonb_build_object('key',source_key,'token',snapshot_token)))) payload from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001') where name='synthetic salt';
select lives_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001',gen_random_uuid(),(select payload from grouped_review))$$,'Grouped equivalent rows apply in one transaction');
select is((select count(*) from cooksmith.household_pantry_items where name='synthetic salt'),1::bigint,'Equivalent purchases create one Pantry item');
select is((select count(*) from cooksmith.shopping_put_away_receipts where planned_meal_id='98000000-0000-4000-8000-000000000030'),2::bigint,'Each original contribution receives a receipt');
select is((select count(*) from cooksmith.shopping_item_contributions where planned_meal_id='98000000-0000-4000-8000-000000000030'),2::bigint,'CS-101 contribution provenance stays intact');
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000030','[{"name":"synthetic salt","quantity":10,"unit":"g","category":"pantry"},{"name":"synthetic salt","quantity":1,"unit":"tsp","category":"pantry"}]');
select is((select count(*) from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001') where name='synthetic salt'),0::bigint,'Regenerating the same purchase cannot offer put-away again');
update cooksmith.shopping_item_contributions set id=gen_random_uuid(),source_quantities=(select jsonb_agg(value || '{"sourceRecipeVersion":"refreshed-version"}'::jsonb) from jsonb_array_elements(source_quantities)) where planned_meal_id='98000000-0000-4000-8000-000000000030' and unit='g';
select is((select count(*) from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001') where name='synthetic salt'),0::bigint,'Equivalent CS-101 replacement provenance cannot replay as a new contribution');
select cooksmith.update_shopping_purchase('20000000-0000-4000-8000-000000000001',(select jsonb_agg(jsonb_build_object('id',id,'name',display_name,'quantity',quantity,'unit',unit,'category',category)) from cooksmith.shopping_list_items where display_name='synthetic salt'));
delete from cooksmith.planned_meals where id='98000000-0000-4000-8000-000000000030';
select is((select count(*) from cooksmith.shopping_list_items where display_name='synthetic salt' and manual),2::bigint,'Manual overrides survive removal of their plan');
select is((select count(*) from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001') where name='synthetic salt'),0::bigint,'Orphan overrides do not replay as new manual stock');
insert into cooksmith.planned_meals(id,household_id,title,meal_date,meal_type) values('98000000-0000-4000-8000-000000000031','20000000-0000-4000-8000-000000000001','Another purchase','2026-10-08','dinner');
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000031','[{"name":"synthetic salt","quantity":20,"unit":"g","category":"pantry"}]');
select cooksmith.set_shopping_purchase_completed('20000000-0000-4000-8000-000000000001',(select array_agg(id) from cooksmith.shopping_list_items where display_name='synthetic salt'),true);
select is((select count(*) from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001') where planned_meal_id='98000000-0000-4000-8000-000000000031'),1::bigint,'A different meal is a genuinely new purchase of the same ingredient');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select is((select count(*) from cooksmith.shopping_put_away_receipts),0::bigint,'Unrelated household cannot read receipts');
select is((select count(*) from cooksmith.shopping_put_away_sources('20000000-0000-4000-8000-000000000001')),0::bigint,'Forged household cannot list purchase sources');
select throws_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001',gen_random_uuid(),(select payload from reviewed))$$,'42501',null,'Forged household cannot apply sources');
select throws_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000002',gen_random_uuid(),(select payload from reviewed))$$,'PT409',null,'Own household cannot use foreign purchase identifiers');
reset role;
update cooksmith.household_members set status='inactive',inactive_at=now() where user_id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select throws_ok($$select cooksmith.put_shopping_away('20000000-0000-4000-8000-000000000001',gen_random_uuid(),(select payload from reviewed))$$,'42501',null,'Inactive member cannot apply purchases');
reset role;
select ok(not has_function_privilege('anon','cooksmith.put_shopping_away(uuid,uuid,jsonb)','execute'),'Anonymous apply denied');
select ok(not has_function_privilege('anon','cooksmith.shopping_put_away_sources(uuid)','execute'),'Anonymous purchase review denied');
select * from finish();
rollback;
